    if (Video.isEmpty(video)) {
        return;
    }

    int currentPosition = mPlaylist.indexOf(video);

    if (currentPosition >= 0) {
        mCurrentIndex = currentPosition;
    } else {
        add(video);
        mCurrentIndex = mPlaylist.size() - 1;
    }
}

