        mPlaylist = new ArrayList<>();
        mSyncedItems = new ArrayList<>();
        mCurrentIndex = -1;
        mPlaylistMaxSize = Utils.isEnoughRam() ? HIGH_RAM_PLAYLIST_MAX_SIZE : LOW_RAM_PLAYLIST_MAX_SIZE;
